using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Threading;using System.Threading.Tasks;
namespace ExtremeLand {public sealed partial class Engine {
 public bool BackendRunning(){if(TestMode)return false;foreach(var p in Process.GetProcessesByName("prismlauncher")){try{if(String.Equals(Path.GetFullPath(p.MainModule.FileName),Path.GetFullPath(Backend),StringComparison.OrdinalIgnoreCase))return true;}catch{return true;}finally{p.Dispose();}}return false;}
 public void Idle(){if(BackendRunning())throw new IOException("Cierra Minecraft y la ventana de acceso de ExtremeLand antes de actualizar.");string saves=Path.Combine(Game,"saves");if(Directory.Exists(saves))foreach(var d in Directory.GetDirectories(saves)){string l=Path.Combine(d,"session.lock");if(File.Exists(l))using(File.Open(l,FileMode.Open,FileAccess.Read,FileShare.None)){};}string mods=Path.Combine(Game,"mods");if(Directory.Exists(mods))foreach(var f in Directory.GetFiles(mods,"*.jar"))using(File.Open(f,FileMode.Open,FileAccess.Read,FileShare.None)){};}
 public async Task Apply(Pack pack,int ram,CancellationToken ct){Validate(pack);Idle();using(var updateLock=new FileStream(Safe("update.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){
  Pack old=File.Exists(Safe("installed.json"))?Json.Read<Pack>(Safe("installed.json")):null;if(old!=null)Validate(old);var stage=new Dictionary<string,string>();int i=0;foreach(var f in pack.files){ct.ThrowIfCancellationRequested();string target=Safe("prism-data/instances/ExtremeLand/.minecraft/"+f.path);Progress("Revisando "+(++i)+"/"+pack.files.Count+" · "+Path.GetFileName(f.path),0,0);if(File.Exists(target)&&new FileInfo(target).Length==f.size&&Hash(target)==f.sha256)continue;stage[f.path]=await Download(f.url,f.sha256,f.size,Path.GetFileName(f.path),ct);}
  ct.ThrowIfCancellationRequested();Idle();string tx=Guid.NewGuid().ToString("N");var touched=new Dictionary<string,string>();int applied=0;
  try{var remove=old==null?new List<string>():old.files.Select(f=>f.path).Where(path=>!pack.files.Any(f=>String.Equals(f.path,path,StringComparison.OrdinalIgnoreCase))).ToList();foreach(var rel in stage.Keys.Concat(remove).Distinct()){string target=Safe("prism-data/instances/ExtremeLand/.minecraft/"+rel),backup=null;if(File.Exists(target)){backup=Safe("backups/"+tx+"/"+rel);Directory.CreateDirectory(Path.GetDirectoryName(backup));File.Move(target,backup);}touched[target]=backup;string cached;if(stage.TryGetValue(rel,out cached)){Directory.CreateDirectory(Path.GetDirectoryName(target));string temp=target+".pending";File.Copy(cached,temp,true);File.Move(temp,target);}if(TestMode&&TestFaultAfter>=0&&++applied>=TestFaultAfter)throw new IOException("Injected commit failure");}
   InstanceFiles(pack,ram);Json.Write(Safe("installed.json"),pack);
  }catch{foreach(var change in touched.Reverse()){if(File.Exists(change.Key))File.Delete(change.Key);if(change.Value!=null&&File.Exists(change.Value))File.Move(change.Value,change.Key);}throw;}
  Progress("Paquete "+pack.version+" preparado",1,1);
 }}
 public void InstanceFiles(Pack pack,int ram){bool freshConfig=!File.Exists(Path.Combine(Instance,"instance.cfg"));Directory.CreateDirectory(Instance);Directory.CreateDirectory(Game);Json.Write(Path.Combine(Instance,"mmc-pack.json"),new{formatVersion=1,components=new[]{new{uid="net.minecraft",version=pack.minecraft},new{uid="net.minecraftforge",version=pack.forge}}});SetIni(Path.Combine(Instance,"instance.cfg"),new Dictionary<string,string>{{"InstanceType","OneSix"},{"name","ExtremeLand · Temporada 1"},{"iconKey","default"},{"OverrideMemory","true"},{"MinMemAlloc","1024"},{"MaxMemAlloc",Math.Max(2048,Math.Min(12288,ram)).ToString()},{"OverrideMiscellaneous","true"},{"CloseAfterLaunch","false"},{"QuitAfterGameStop","true"}});if(freshConfig){string nettmp=Safe("nettmp");Directory.CreateDirectory(nettmp);SetIni(Path.Combine(Instance,"instance.cfg"),new Dictionary<string,string>{{"OverrideJavaArgs","true"},{"JvmArgs","-Djdk.net.unixdomain.tmpdir=\""+nettmp.Replace('\\','/')+"\""}});}Directory.CreateDirectory(PrismData);SetIni(Path.Combine(PrismData,"prismlauncher.cfg"),new Dictionary<string,string>{{"AutomaticJavaSwitch","true"},{"AutomaticJavaDownload","true"}});}
 public static void SetIni(string path,Dictionary<string,string> values){var lines=File.Exists(path)?File.ReadAllLines(path).ToList():new List<string>{"[General]"};if(!lines.Any(l=>l.Trim()=="[General]"))lines.Insert(0,"[General]");int start=lines.FindIndex(l=>l.Trim()=="[General]"),end=lines.FindIndex(start+1,l=>l.StartsWith("["));if(end<0)end=lines.Count;foreach(var pair in values){int at=lines.FindIndex(start+1,end-start-1,l=>l.StartsWith(pair.Key+"=",StringComparison.Ordinal));string line=pair.Key+"="+pair.Value;if(at>=0)lines[at]=line;else lines.Insert(end++,line);}Json.Atomic(path,String.Join("\n",lines)+"\n");}
 public string ImportWorld(string source){Idle();source=Path.GetFullPath(source).TrimEnd(Path.DirectorySeparatorChar);if(!File.Exists(Path.Combine(source,"level.dat")))throw new IOException("Selecciona la carpeta del mundo que contiene level.dat.");string name=Path.GetFileName(source.TrimEnd(Path.DirectorySeparatorChar));if(String.IsNullOrEmpty(name)||name=="..")throw new IOException("Nombre de mundo inválido.");string target=Safe("prism-data/instances/ExtremeLand/.minecraft/saves/"+name);if(Directory.Exists(target))target+="-copia-"+DateTime.Now.ToString("yyyyMMdd-HHmmss");if(target.StartsWith(source+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new IOException("Selecciona un mundo externo a la carpeta de destino.");string session=Path.Combine(source,"session.lock");using(var check=File.Exists(session)?File.Open(session,FileMode.Open,FileAccess.Read,FileShare.None):null){CopyTree(source,target);}return target;}
 static void CopyTree(string source,string target){RejectLinks(source);Directory.CreateDirectory(target);foreach(var f in Directory.GetFiles(source)){if(Path.GetFileName(f)=="session.lock")continue;RejectLinks(f);File.Copy(f,Path.Combine(target,Path.GetFileName(f)),false);}foreach(var d in Directory.GetDirectories(source))CopyTree(d,Path.Combine(target,Path.GetFileName(d)));}
}}
